import { mkdir, readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const schema = new URL("../openapi.json", import.meta.url);
const directory = new URL("../../frontend/quezo/src/lib/api/", import.meta.url);
const output = new URL("schema.d.ts", directory);
const content =
  "// Generated by npm run api:generate. Do not edit.\n" +
  astToString(await openapiTS(schema, { defaultNonNullable: false }));

if (process.argv.includes("--check")) {
  let existing;
  try {
    existing = await readFile(output, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  if (existing?.replaceAll("\r\n", "\n") !== content) {
    console.error("TypeScript API types are stale. Run npm run api:generate.");
    process.exitCode = 1;
  } else {
    console.log("TypeScript API types are current.");
  }
} else {
  await mkdir(directory, { recursive: true });
  await writeFile(output, content, "utf8");
  console.log("Generated frontend/quezo/src/lib/api/schema.d.ts.");
}
